-- 中文 N1 課程（Mandarin Training (Kolecion)）：依「場合」分類，新增 19 個生活與工作溝通單元（買菜、餐廳、搭車、匯款、請假、安全警告、看醫生…），
-- 每個單元都有詞彙、例句與對話（中文 | 拼音 | 英文），並替既有 8 個單元補上場合分類。
-- 可重複執行：已存在的單元（名稱相同）不會被覆蓋；只有「這次真的新增了單元」才會重新排列順序，之後再執行不會動到你調整過的順序。
-- 既有單元（發音與聲調、日常生活…）都保留，工人已經記錄的學習進度不會消失。
--
-- 請先執行過 seed-training-courses.sql（建立課程與原本 8 個單元），再用（在專案資料夾，center_email 換成訓練中心會員的 Email）：
--   Get-Content scripts/seed-mandarin-scenario-units.sql | docker compose exec -T postgres psql -U postgres -d saas_demo -v center_email=center@example.com
--
-- 注意：新增單元的時數合計為 38 小時，加上原本 60 小時，單元時數合計會超過課程的「課程時數」；課程時數與費用不會被這支腳本修改，請自行決定是否調整。
\set ON_ERROR_STOP on

-- 找不到訓練中心或課程就中止，不寫入任何資料。
SELECT COALESCE(max(id), 0) AS center_id FROM hr_members
WHERE role = 'training_center' AND lower(email) = lower(:'center_email') \gset
SELECT :center_id = 0 AS missing_center \gset
\if :missing_center
  \echo '找不到這個 Email 的訓練中心會員（會員類型必須是訓練中心），已中止。'
  \quit
\endif
SELECT COALESCE(max(id), 0) AS course_id FROM hr_tc_courses
WHERE center_id = :center_id AND name = 'Mandarin Training (Kolecion)' \gset
SELECT :course_id = 0 AS missing_course \gset
\if :missing_course
  \echo '找不到 Mandarin Training (Kolecion) 課程，請先執行 seed-training-courses.sql，已中止。'
  \quit
\endif

BEGIN;

-- 場合分類欄位（網站更新後也會自動建立，這裡先補上以免順序問題）。
ALTER TABLE hr_tc_course_units ADD COLUMN IF NOT EXISTS vocabulary TEXT NOT NULL DEFAULT '';
ALTER TABLE hr_tc_course_units ADD COLUMN IF NOT EXISTS dialogue TEXT NOT NULL DEFAULT '';
ALTER TABLE hr_tc_course_units ADD COLUMN IF NOT EXISTS category TEXT NOT NULL DEFAULT '';
ALTER TABLE hr_tc_course_units ADD COLUMN IF NOT EXISTS category_en TEXT NOT NULL DEFAULT '';

-- 新增單元（名稱相同的不會覆蓋）。
WITH inserted AS (
  INSERT INTO hr_tc_course_units(center_id, course_id, position, name, name_en, hours, topics, topics_en, examples, vocabulary, dialogue, category, category_en)
  SELECT :center_id, :course_id, v.position, v.name, v.name_en, v.hours, v.topics, v.topics_en, v.examples, v.vocabulary, v.dialogue, v.category, v.category_en
  FROM (VALUES
    (5, E'買菜與市場', E'Buying Groceries at the Market', 2, E'在菜市場問價、秤重、議價、付錢、要袋子', E'Asking prices, weighing, bargaining, paying and asking for a bag at the market', E'老闆，這個怎麼賣？ | Lǎobǎn, zhège zěnme mài? | Boss, how much is this?\n我要兩斤青菜。 | Wǒ yào liǎng jīn qīngcài. | I want two jin of greens.\n可以算便宜一點嗎？ | Kěyǐ suàn piányí yìdiǎn ma? | Can you make it a bit cheaper?', E'菜市場 | cài shìchǎng | wet market\n青菜 | qīngcài | leafy greens\n水果 | shuǐguǒ | fruit\n雞蛋 | jīdàn | eggs\n豬肉 | zhūròu | pork\n魚 | yú | fish\n一斤 | yì jīn | one jin (about 600 g)\n多少錢 | duōshǎo qián | how much (money)\n太貴了 | tài guì le | too expensive\n便宜一點 | piányí yìdiǎn | a little cheaper\n袋子 | dàizi | bag\n找錢 | zhǎo qián | to give change', E'A：老闆，這些青菜怎麼賣？ | Lǎobǎn, zhèxiē qīngcài zěnme mài? | Boss, how much are these greens?\nB：一斤三十元。 | Yì jīn sānshí yuán. | Thirty dollars per jin.\nA：我要兩斤，可以算便宜一點嗎？ | Wǒ yào liǎng jīn, kěyǐ suàn piányí yìdiǎn ma? | I want two jin. Can you make it a bit cheaper?\nB：好啦，兩斤五十五元。 | Hǎo la, liǎng jīn wǔshíwǔ yuán. | OK, 55 dollars for two jin.\nA：再給我六顆雞蛋，要袋子。 | Zài gěi wǒ liù kē jīdàn, yào dàizi. | Also give me six eggs, and a bag please.\nB：一共八十五元，謝謝。 | Yígòng bāshíwǔ yuán, xièxie. | 85 dollars in total, thank you.', E'購物與飲食', E'Shopping & Food'),
    (6, E'便利商店與超市', E'Convenience Stores & Supermarkets', 2, E'結帳、付現或刷卡、要不要袋子、加熱食物、發票與特價', E'Checking out, paying by cash or card, bags, heating food, receipts and special offers', E'請幫我加熱。 | Qǐng bāng wǒ jiārè. | Please heat this up for me.\n我不需要袋子。 | Wǒ bù xūyào dàizi. | I don''t need a bag.\n可以刷卡嗎？ | Kěyǐ shuā kǎ ma? | Can I pay by card?', E'便利商店 | biànlì shāngdiàn | convenience store\n超市 | chāoshì | supermarket\n便當 | biàndāng | lunch box\n結帳 | jiézhàng | to check out\n加熱 | jiārè | to heat up\n塑膠袋 | sùjiāodài | plastic bag\n現金 | xiànjīn | cash\n刷卡 | shuā kǎ | to pay by card\n發票 | fāpiào | receipt\n特價 | tèjià | special price\n買一送一 | mǎi yí sòng yī | buy one, get one free\n會員卡 | huìyuánkǎ | membership card', E'A：請問這個便當可以幫我加熱嗎？ | Qǐngwèn zhège biàndāng kěyǐ bāng wǒ jiārè ma? | Excuse me, can you heat this lunch box for me?\nB：可以，請等一下。 | Kěyǐ, qǐng děng yíxià. | Sure, please wait a moment.\nB：一共九十五元，需要塑膠袋嗎？ | Yígòng jiǔshíwǔ yuán, xūyào sùjiāodài ma? | 95 dollars in total. Do you need a plastic bag?\nA：不用，我自己有帶袋子。 | Búyòng, wǒ zìjǐ yǒu dài dàizi. | No need, I brought my own bag.\nA：我可以刷卡嗎？ | Wǒ kěyǐ shuā kǎ ma? | Can I pay by card?\nB：可以。這是您的發票，謝謝光臨。 | Kěyǐ. Zhè shì nín de fāpiào, xièxie guānglín. | Yes. Here is your receipt. Thank you for coming.', E'購物與飲食', E'Shopping & Food'),
    (7, E'餐廳點餐', E'Ordering at a Restaurant', 2, E'入座、看菜單、點菜、忌口、內用或外帶、買單', E'Being seated, reading the menu, ordering, dietary requests, eating in or taking out, paying the bill', E'請給我菜單。 | Qǐng gěi wǒ càidān. | Please give me the menu.\n我要一碗牛肉麵。 | Wǒ yào yì wǎn niúròumiàn. | I would like a bowl of beef noodles.\n請問可以不要辣嗎？ | Qǐngwèn kěyǐ búyào là ma? | Excuse me, can it be not spicy?', E'菜單 | càidān | menu\n點菜 | diǎn cài | to order food\n內用 | nèiyòng | eat in\n外帶 | wàidài | takeout\n飲料 | yǐnliào | drink\n白飯 | báifàn | plain rice\n不要辣 | búyào là | not spicy\n素食 | sùshí | vegetarian food\n筷子 | kuàizi | chopsticks\n好吃 | hǎochī | delicious\n買單 | mǎidān | to pay the bill\n再來一碗 | zài lái yì wǎn | another bowl, please', E'A：歡迎光臨，請問幾位？ | Huānyíng guānglín, qǐngwèn jǐ wèi? | Welcome. How many people?\nB：兩位，內用。 | Liǎng wèi, nèiyòng. | Two people, eating in.\nA：這是菜單。請問要點什麼？ | Zhè shì càidān. Qǐngwèn yào diǎn shénme? | Here is the menu. What would you like to order?\nB：我要一份炒飯，不要辣。 | Wǒ yào yí fèn chǎofàn, búyào là. | I''d like a fried rice, not spicy.\nA：好的，請問要喝飲料嗎？ | Hǎo de, qǐngwèn yào hē yǐnliào ma? | OK, would you like a drink?\nB：一杯紅茶。等一下請幫我買單。 | Yì bēi hóngchá. Děng yíxià qǐng bāng wǒ mǎidān. | A cup of black tea. Please bring the bill later.', E'購物與飲食', E'Shopping & Food'),
    (8, E'公車與捷運', E'Taking Buses & the MRT', 2, E'問搭哪一條線、買票與儲值、下一站、轉車、出口', E'Asking which line to take, tickets and top-ups, the next stop, transfers and exits', E'請問這輛公車到火車站嗎？ | Qǐngwèn zhè liàng gōngchē dào huǒchēzhàn ma? | Excuse me, does this bus go to the train station?\n我要在下一站下車。 | Wǒ yào zài xià yí zhàn xiàchē. | I''m getting off at the next stop.\n悠遊卡沒錢了，我要儲值。 | Yōuyóukǎ méi qián le, wǒ yào chǔzhí. | My EasyCard has no money left. I need to top it up.', E'公車 | gōngchē | bus\n捷運 | jiéyùn | MRT, metro\n車站 | chēzhàn | station\n悠遊卡 | yōuyóukǎ | EasyCard\n儲值 | chǔzhí | to top up\n單程票 | dānchéngpiào | single-journey ticket\n下一站 | xià yí zhàn | next stop\n轉車 | zhuǎnchē | to transfer\n出口 | chūkǒu | exit\n讓座 | ràng zuò | to give up one''s seat\n下車 | xiàchē | to get off', E'A：請問去台北車站要搭哪一條線？ | Qǐngwèn qù Táiběi Chēzhàn yào dā nǎ yì tiáo xiàn? | Excuse me, which line should I take to Taipei Main Station?\nB：搭藍線，坐三站就到了。 | Dā lán xiàn, zuò sān zhàn jiù dào le. | Take the blue line; it''s three stops.\nA：我要怎麼買票？ | Wǒ yào zěnme mǎi piào? | How do I buy a ticket?\nB：你可以用悠遊卡，也可以買單程票。 | Nǐ kěyǐ yòng yōuyóukǎ, yě kěyǐ mǎi dānchéngpiào. | You can use an EasyCard or buy a single-journey ticket.\nA：下一站是哪裡？ | Xià yí zhàn shì nǎlǐ? | What is the next stop?\nB：下一站就是台北車站，要下車了。 | Xià yí zhàn jiù shì Táiběi Chēzhàn, yào xiàchē le. | The next stop is Taipei Main Station. Time to get off.', E'交通與出行', E'Getting Around'),
    (9, E'火車與高鐵', E'Trains & High-Speed Rail', 2, E'買車票、單程或來回、對號座、月台、誤點', E'Buying tickets, one-way or round trip, reserved seats, platforms and delays', E'我要買一張到台中的車票。 | Wǒ yào mǎi yì zhāng dào Táizhōng de chēpiào. | I want to buy a ticket to Taichung.\n請問這班車幾點發車？ | Qǐngwèn zhè bān chē jǐ diǎn fāchē? | What time does this train depart?\n請問這個座位有人坐嗎？ | Qǐngwèn zhège zuòwèi yǒu rén zuò ma? | Is this seat taken?', E'火車 | huǒchē | train\n高鐵 | gāotiě | high-speed rail\n車票 | chēpiào | ticket\n單程 | dānchéng | one way\n來回 | láihuí | round trip\n對號座 | duìhàozuò | reserved seat\n自由座 | zìyóuzuò | non-reserved seat\n月台 | yuètái | platform\n座位 | zuòwèi | seat\n發車 | fāchē | to depart\n誤點 | wùdiǎn | delayed\n自動售票機 | zìdòng shòupiàojī | ticket machine', E'A：您好，我要買一張到高雄的高鐵票。 | Nín hǎo, wǒ yào mǎi yì zhāng dào Gāoxióng de gāotiě piào. | Hello, I want a high-speed rail ticket to Kaohsiung.\nB：請問要單程還是來回？ | Qǐngwèn yào dānchéng háishi láihuí? | One way or round trip?\nA：單程，要對號座。 | Dānchéng, yào duìhàozuò. | One way, with a reserved seat.\nB：好的，下午兩點的車可以嗎？ | Hǎo de, xiàwǔ liǎng diǎn de chē kěyǐ ma? | OK, is the 2 p.m. train fine?\nA：可以。請問在幾號月台上車？ | Kěyǐ. Qǐngwèn zài jǐ hào yuètái shàngchē? | Fine. Which platform do I board from?\nB：請看車票，上面有寫月台和座位。 | Qǐng kàn chēpiào, shàngmiàn yǒu xiě yuètái hé zuòwèi. | Please check the ticket; the platform and seat are written on it.', E'交通與出行', E'Getting Around'),
    (10, E'問路與計程車', E'Asking Directions & Taking a Taxi', 2, E'問路、說明方向、搭計程車、說出地址', E'Asking for directions, giving directions, taking a taxi and giving an address', E'請問郵局在哪裡？ | Qǐngwèn yóujú zài nǎlǐ? | Excuse me, where is the post office?\n直走，到紅綠燈右轉。 | Zhí zǒu, dào hónglǜdēng yòu zhuǎn. | Go straight, then turn right at the traffic light.\n請載我到這個地址。 | Qǐng zài wǒ dào zhège dìzhǐ. | Please take me to this address.', E'請問 | qǐngwèn | excuse me\n在哪裡 | zài nǎlǐ | where is\n附近 | fùjìn | nearby\n左邊 | zuǒbiān | left side\n右邊 | yòubiān | right side\n直走 | zhí zǒu | go straight\n轉彎 | zhuǎnwān | to turn\n紅綠燈 | hónglǜdēng | traffic light\n旁邊 | pángbiān | beside\n郵局 | yóujú | post office\n計程車 | jìchéngchē | taxi\n地址 | dìzhǐ | address', E'A：請問附近有便利商店嗎？ | Qǐngwèn fùjìn yǒu biànlì shāngdiàn ma? | Excuse me, is there a convenience store nearby?\nB：有，你直走，到紅綠燈右轉。 | Yǒu, nǐ zhí zǒu, dào hónglǜdēng yòu zhuǎn. | Yes. Go straight and turn right at the traffic light.\nA：右轉以後呢？ | Yòu zhuǎn yǐhòu ne? | And after turning right?\nB：它就在郵局旁邊，很近。 | Tā jiù zài yóujú pángbiān, hěn jìn. | It''s right beside the post office, very close.\nA：謝謝你！ | Xièxie nǐ! | Thank you!\nB：不客氣。 | Bú kèqi. | You''re welcome.', E'交通與出行', E'Getting Around'),
    (12, E'宿舍報修與生活規則', E'Dormitory Repairs & House Rules', 2, E'設備壞了怎麼說、停水停電、倒垃圾與資源回收、宿舍規定', E'Reporting broken equipment, water and power outages, trash and recycling, dormitory rules', E'熱水器壞了，可以請人來修嗎？ | Rèshuǐqì huài le, kěyǐ qǐng rén lái xiū ma? | The water heater is broken. Can someone come and fix it?\n今天晚上停水嗎？ | Jīntiān wǎnshang tíngshuǐ ma? | Is the water going to be cut off tonight?\n請問垃圾要什麼時候丟？ | Qǐngwèn lājī yào shénme shíhou diū? | When should the trash be thrown out?', E'室友 | shìyǒu | roommate\n房東 | fángdōng | landlord\n師傅 | shīfu | technician\n熱水器 | rèshuǐqì | water heater\n冷氣 | lěngqì | air conditioner\n壞了 | huài le | broken\n修理 | xiūlǐ | to repair\n停水 | tíngshuǐ | water outage\n停電 | tíngdiàn | power outage\n垃圾車 | lājīchē | garbage truck\n資源回收 | zīyuán huíshōu | recycling\n門禁 | ménjìn | curfew', E'A：房東先生，我的房間冷氣壞了。 | Fángdōng xiānshēng, wǒ de fángjiān lěngqì huài le. | Landlord, the air conditioner in my room is broken.\nB：什麼時候壞的？ | Shénme shíhou huài de? | When did it break?\nA：昨天晚上開始，一直不冷。 | Zuótiān wǎnshang kāishǐ, yìzhí bù lěng. | Since last night, it hasn''t been cooling.\nB：好，我明天請師傅來修理。 | Hǎo, wǒ míngtiān qǐng shīfu lái xiūlǐ. | OK, I''ll ask a technician to come and repair it tomorrow.\nA：謝謝。另外，垃圾要什麼時候丟？ | Xièxie. Lìngwài, lājī yào shénme shíhou diū? | Thanks. Also, when should we throw out the trash?\nB：晚上七點，垃圾車會來。 | Wǎnshang qī diǎn, lājīchē huì lái. | At 7 p.m. the garbage truck comes.', E'住宿與生活服務', E'Housing & Services'),
    (13, E'銀行與匯款', E'Banking & Sending Money Home', 2, E'開戶、存款提款、匯款回家、匯率與手續費、需要帶的證件', E'Opening an account, deposits and withdrawals, remitting money home, exchange rates, fees and required documents', E'我想開一個帳戶。 | Wǒ xiǎng kāi yí ge zhànghù. | I''d like to open an account.\n我要匯錢到菲律賓。 | Wǒ yào huì qián dào Fēilǜbīn. | I want to send money to the Philippines.\n手續費是多少？ | Shǒuxùfèi shì duōshǎo? | How much is the fee?', E'銀行 | yínháng | bank\n帳戶 | zhànghù | account\n存款 | cúnkuǎn | to deposit\n提款機 | tíkuǎnjī | ATM\n匯款 | huìkuǎn | to remit money\n匯率 | huìlǜ | exchange rate\n手續費 | shǒuxùfèi | service fee\n存摺 | cúnzhé | passbook\n護照 | hùzhào | passport\n居留證 | jūliúzhèng | resident certificate (ARC)\n密碼 | mìmǎ | PIN, password\n菲律賓披索 | Fēilǜbīn pīsuǒ | Philippine peso', E'A：您好，我想匯款到菲律賓。 | Nín hǎo, wǒ xiǎng huìkuǎn dào Fēilǜbīn. | Hello, I''d like to send money to the Philippines.\nB：請給我您的護照和居留證。 | Qǐng gěi wǒ nín de hùzhào hé jūliúzhèng. | Please give me your passport and ARC.\nA：好的。今天的匯率是多少？ | Hǎo de. Jīntiān de huìlǜ shì duōshǎo? | OK. What is today''s exchange rate?\nB：請看這張表，上面有今天的匯率。 | Qǐng kàn zhè zhāng biǎo, shàngmiàn yǒu jīntiān de huìlǜ. | Please look at this table; today''s rate is on it.\nA：手續費是多少？ | Shǒuxùfèi shì duōshǎo? | How much is the fee?\nB：一筆一百五十元。 | Yì bǐ yìbǎi wǔshí yuán. | 150 dollars per transfer.', E'住宿與生活服務', E'Housing & Services'),
    (14, E'打電話與傳訊息', E'Phone Calls & Messaging', 2, E'接打電話、轉接與留言、聽不清楚怎麼說、傳訊息', E'Making and answering calls, transfers and messages, what to say when you cannot hear, sending messages', E'喂，請問王先生在嗎？ | Wéi, qǐngwèn Wáng xiānshēng zài ma? | Hello, is Mr. Wang there?\n不好意思，我聽不清楚。 | Bù hǎoyìsi, wǒ tīng bù qīngchu. | Sorry, I can''t hear clearly.\n我手機沒電了，等一下回電給你。 | Wǒ shǒujī méi diàn le, děng yíxià huídiàn gěi nǐ. | My phone is out of battery; I''ll call you back in a moment.', E'手機 | shǒujī | mobile phone\n打電話 | dǎ diànhuà | to make a call\n接電話 | jiē diànhuà | to answer the phone\n等一下 | děng yíxià | wait a moment\n不在 | bú zài | not here\n留言 | liúyán | to leave a message\n回電 | huídiàn | to call back\n訊息 | xùnxí | message\n傳 | chuán | to send\n聽不清楚 | tīng bù qīngchu | cannot hear clearly\n沒電 | méi diàn | out of battery\n請再說一次 | qǐng zài shuō yí cì | please say it again', E'A：喂，您好，請問王主任在嗎？ | Wéi, nín hǎo, qǐngwèn Wáng zhǔrèn zài ma? | Hello, is Director Wang there?\nB：他現在不在，請問你是哪位？ | Tā xiànzài bú zài, qǐngwèn nǐ shì nǎ wèi? | He''s not here now. Who is calling?\nA：我是新來的工人，我叫瑪莉亞。 | Wǒ shì xīn lái de gōngrén, wǒ jiào Mǎlìyà. | I''m a new worker, my name is Maria.\nB：好，需要留言嗎？ | Hǎo, xūyào liúyán ma? | OK, would you like to leave a message?\nA：請他回電給我，謝謝。 | Qǐng tā huídiàn gěi wǒ, xièxie. | Please ask him to call me back, thank you.\nB：沒問題，再見。 | Méi wèntí, zàijiàn. | No problem, goodbye.', E'住宿與生活服務', E'Housing & Services'),
    (16, E'報到與認識同事', E'First Day & Meeting Coworkers', 2, E'報到、自我介紹、認識主管與同事、打卡與上下班', E'Checking in, introducing yourself, meeting supervisors and coworkers, clocking in and out', E'我是今天來報到的。 | Wǒ shì jīntiān lái bàodào de. | I''m here to check in today.\n請問我的工作時間是幾點到幾點？ | Qǐngwèn wǒ de gōngzuò shíjiān shì jǐ diǎn dào jǐ diǎn? | What are my working hours?\n我每天要打卡。 | Wǒ měitiān yào dǎkǎ. | I have to clock in every day.', E'報到 | bàodào | to check in\n公司 | gōngsī | company\n工廠 | gōngchǎng | factory\n老闆 | lǎobǎn | boss\n主管 | zhǔguǎn | supervisor\n同事 | tóngshì | coworker\n工作證 | gōngzuòzhèng | work ID\n打卡 | dǎkǎ | to clock in\n上班 | shàngbān | to go to work\n下班 | xiàbān | to finish work\n更衣室 | gēngyīshì | changing room\n請多多指教 | qǐng duōduō zhǐjiào | please give me your guidance', E'A：您好，我是今天來報到的瑪莉亞。 | Nín hǎo, wǒ shì jīntiān lái bàodào de Mǎlìyà. | Hello, I''m Maria, here to check in today.\nB：歡迎你。我是你的主管，我姓林。 | Huānyíng nǐ. Wǒ shì nǐ de zhǔguǎn, wǒ xìng Lín. | Welcome. I''m your supervisor; my surname is Lin.\nA：林主管好，請多多指教。 | Lín zhǔguǎn hǎo, qǐng duōduō zhǐjiào. | Hello, Supervisor Lin. Please give me your guidance.\nB：這是你的工作證，每天上班和下班都要打卡。 | Zhè shì nǐ de gōngzuòzhèng, měitiān shàngbān hé xiàbān dōu yào dǎkǎ. | This is your work ID. You must clock in when starting and finishing work each day.\nA：好的，我知道了。更衣室在哪裡？ | Hǎo de, wǒ zhīdào le. Gēngyīshì zài nǎlǐ? | OK, I understand. Where is the changing room?\nB：在二樓，我帶你去。 | Zài èr lóu, wǒ dài nǐ qù. | On the second floor. I''ll take you there.', E'職場溝通', E'Workplace Communication'),
    (17, E'聽懂主管指令', E'Understanding a Supervisor''s Instructions', 2, E'聽懂工作指令、先後順序、請對方再說一次、完成後回報', E'Understanding work instructions, sequence of tasks, asking someone to repeat, reporting when done', E'請先把這些箱子搬到倉庫。 | Qǐng xiān bǎ zhèxiē xiāngzi bān dào cāngkù. | Please first move these boxes to the warehouse.\n做完以後，請告訴我。 | Zuò wán yǐhòu, qǐng gàosù wǒ. | When you''re done, please tell me.\n我不懂，請你再說一次。 | Wǒ bù dǒng, qǐng nǐ zài shuō yí cì. | I don''t understand. Please say it again.', E'搬 | bān | to carry, to move\n箱子 | xiāngzi | box\n倉庫 | cāngkù | warehouse\n放在這裡 | fàng zài zhèlǐ | put it here\n檢查 | jiǎnchá | to check, to inspect\n整理 | zhěnglǐ | to tidy up\n打掃 | dǎsǎo | to clean\n快一點 | kuài yìdiǎn | faster\n慢一點 | màn yìdiǎn | slower\n做完 | zuò wán | to finish doing\n注意 | zhùyì | to pay attention\n告訴我 | gàosù wǒ | tell me', E'A：瑪莉亞，請先把這些箱子搬到倉庫。 | Mǎlìyà, qǐng xiān bǎ zhèxiē xiāngzi bān dào cāngkù. | Maria, please first carry these boxes to the warehouse.\nB：好的。倉庫是哪一間？ | Hǎo de. Cāngkù shì nǎ yì jiān? | OK. Which room is the warehouse?\nA：走廊最後面那一間。 | Zǒuláng zuì hòumiàn nà yì jiān. | The last one at the end of the corridor.\nB：我不太懂，請你慢一點再說一次。 | Wǒ bú tài dǒng, qǐng nǐ màn yìdiǎn zài shuō yí cì. | I don''t quite understand. Please say it again more slowly.\nA：沒問題。搬完以後，再把地板打掃乾淨。 | Méi wèntí. Bān wán yǐhòu, zài bǎ dìbǎn dǎsǎo gānjìng. | No problem. After moving them, sweep the floor clean.\nB：好，我做完會告訴你。 | Hǎo, wǒ zuò wán huì gàosù nǐ. | OK, I''ll tell you when I''m done.', E'職場溝通', E'Workplace Communication'),
    (18, E'請假、遲到與調班', E'Asking for Leave, Being Late & Changing Shifts', 2, E'請病假與事假、遲到早退、調班、診斷證明', E'Sick and personal leave, being late or leaving early, changing shifts, medical certificates', E'我今天不舒服，想請病假。 | Wǒ jīntiān bù shūfu, xiǎng qǐng bìngjià. | I don''t feel well today and want sick leave.\n對不起，我會遲到十分鐘。 | Duìbuqǐ, wǒ huì chídào shí fēn zhōng. | Sorry, I will be ten minutes late.\n可以幫我調班嗎？ | Kěyǐ bāng wǒ diàobān ma? | Can you help me change shifts?', E'請假 | qǐngjià | to ask for leave\n病假 | bìngjià | sick leave\n事假 | shìjià | personal leave\n遲到 | chídào | to be late\n早退 | zǎotuì | to leave early\n調班 | diàobān | to change shifts\n休假 | xiūjià | day off\n發燒 | fāshāo | to have a fever\n醫生 | yīshēng | doctor\n診斷證明 | zhěnduàn zhèngmíng | medical certificate\n對不起 | duìbuqǐ | sorry\n通知 | tōngzhī | to notify', E'A：主管，我今天發燒，想請病假。 | Zhǔguǎn, wǒ jīntiān fāshāo, xiǎng qǐng bìngjià. | Supervisor, I have a fever today and want sick leave.\nB：你去看醫生了嗎？ | Nǐ qù kàn yīshēng le ma? | Have you seen a doctor?\nA：還沒有，我等一下去。 | Hái méiyǒu, wǒ děng yíxià qù. | Not yet. I''ll go in a while.\nB：好，記得拿診斷證明回來。 | Hǎo, jìdé ná zhěnduàn zhèngmíng huílái. | OK. Remember to bring back a medical certificate.\nA：謝謝主管。明天我會回來上班。 | Xièxie zhǔguǎn. Míngtiān wǒ huì huílái shàngbān. | Thank you. I''ll be back at work tomorrow.\nB：好好休息。 | Hǎohāo xiūxí. | Rest well.', E'職場溝通', E'Workplace Communication'),
    (19, E'安全規定與危險警告', E'Safety Rules & Danger Warnings', 2, E'安全裝備、危險警告、禁止事項、緊急出口與滅火器', E'Safety equipment, danger warnings, prohibitions, emergency exits and fire extinguishers', E'工作的時候要戴安全帽。 | Gōngzuò de shíhou yào dài ānquánmào. | You must wear a helmet when working.\n小心！地上很滑。 | Xiǎoxīn! Dìshàng hěn huá. | Careful! The floor is slippery.\n機器有問題，請馬上停。 | Jīqì yǒu wèntí, qǐng mǎshàng tíng. | There''s a problem with the machine. Please stop immediately.', E'安全帽 | ānquánmào | safety helmet\n口罩 | kǒuzhào | face mask\n手套 | shǒutào | gloves\n小心 | xiǎoxīn | careful\n危險 | wēixiǎn | dangerous\n禁止 | jìnzhǐ | prohibited\n地上很滑 | dìshàng hěn huá | the floor is slippery\n緊急出口 | jǐnjí chūkǒu | emergency exit\n滅火器 | mièhuǒqì | fire extinguisher\n機器 | jīqì | machine\n關掉 | guāndiào | to turn off\n停 | tíng | to stop', E'A：瑪莉亞，小心！那台機器很危險。 | Mǎlìyà, xiǎoxīn! Nà tái jīqì hěn wēixiǎn. | Maria, careful! That machine is dangerous.\nB：對不起，我不知道。我可以用嗎？ | Duìbuqǐ, wǒ bù zhīdào. Wǒ kěyǐ yòng ma? | Sorry, I didn''t know. May I use it?\nA：要先戴手套和安全帽才可以。 | Yào xiān dài shǒutào hé ānquánmào cái kěyǐ. | Only after putting on gloves and a helmet.\nB：好的。緊急出口在哪裡？ | Hǎo de. Jǐnjí chūkǒu zài nǎlǐ? | OK. Where is the emergency exit?\nA：在那邊，旁邊有滅火器。 | Zài nàbiān, pángbiān yǒu mièhuǒqì. | Over there. There''s a fire extinguisher beside it.\nB：我記住了，謝謝。 | Wǒ jìzhù le, xièxie. | I''ll remember. Thanks.', E'職場溝通', E'Workplace Communication'),
    (20, E'回報問題與請求協助', E'Reporting Problems & Asking for Help', 2, E'向主管說明問題、說明東西壞了或不夠、借工具、請同事幫忙', E'Explaining problems to a supervisor, saying something is broken or short, borrowing tools, asking coworkers for help', E'主管，這個工具壞掉了。 | Zhǔguǎn, zhège gōngjù huàidiào le. | Supervisor, this tool is broken.\n我找不到材料，可以幫我嗎？ | Wǒ zhǎo bú dào cáiliào, kěyǐ bāng wǒ ma? | I can''t find the materials. Can you help me?\n我不小心受傷了。 | Wǒ bù xiǎoxīn shòushāng le. | I accidentally got hurt.', E'問題 | wèntí | problem\n壞掉 | huàidiào | broken\n不夠 | búgòu | not enough\n找不到 | zhǎo bú dào | cannot find\n幫忙 | bāngmáng | to help\n馬上 | mǎshàng | right away\n受傷 | shòushāng | injured\n材料 | cáiliào | material\n工具 | gōngjù | tool\n梯子 | tīzi | ladder\n借 | jiè | to borrow\n還 | huán | to return', E'A：主管，我有一個問題。 | Zhǔguǎn, wǒ yǒu yí ge wèntí. | Supervisor, I have a problem.\nB：什麼問題？請慢慢說。 | Shénme wèntí? Qǐng mànmàn shuō. | What problem? Please speak slowly.\nA：這個機器停了，我也找不到工具。 | Zhège jīqì tíng le, wǒ yě zhǎo bú dào gōngjù. | This machine has stopped, and I can''t find the tool.\nB：好，你先關掉電源，我馬上過去。 | Hǎo, nǐ xiān guāndiào diànyuán, wǒ mǎshàng guòqù. | OK, switch off the power first. I''ll come right away.\nA：謝謝主管。我還需要借一把梯子。 | Xièxie zhǔguǎn. Wǒ hái xūyào jiè yì bǎ tīzi. | Thank you, Supervisor. I also need to borrow a ladder.\nB：在倉庫裡，用完要還。 | Zài cāngkù lǐ, yòng wán yào huán. | It''s in the warehouse. Return it after you use it.', E'職場溝通', E'Workplace Communication'),
    (21, E'薪水、加班與工時', E'Salary, Overtime & Working Hours', 2, E'發薪日、薪資單、加班與加班費、扣款項目、發現算錯怎麼問', E'Pay day, pay slips, overtime and overtime pay, deductions, how to ask when something seems wrong', E'請問發薪日是幾號？ | Qǐngwèn fāxīnrì shì jǐ hào? | What date is pay day?\n這個月加班幾個小時？ | Zhège yuè jiābān jǐ ge xiǎoshí? | How many hours of overtime this month?\n我覺得薪資單好像算錯了。 | Wǒ juéde xīnzīdān hǎoxiàng suàn cuò le. | I think the pay slip may have been miscalculated.', E'薪水 | xīnshuǐ | salary\n發薪日 | fāxīnrì | pay day\n薪資單 | xīnzīdān | pay slip\n加班 | jiābān | overtime\n加班費 | jiābānfèi | overtime pay\n工時 | gōngshí | working hours\n扣錢 | kòu qián | to deduct money\n勞健保 | láojiànbǎo | labor and health insurance\n伙食費 | huǒshífèi | meal fee\n仲介費 | zhòngjièfèi | agency fee\n算錯 | suàn cuò | to miscalculate\n一個月 | yí ge yuè | one month', E'A：主管，請問發薪日是幾號？ | Zhǔguǎn, qǐngwèn fāxīnrì shì jǐ hào? | Supervisor, what date is pay day?\nB：每個月五號。 | Měi ge yuè wǔ hào. | The 5th of every month.\nA：這個月我加班十個小時，有加班費嗎？ | Zhège yuè wǒ jiābān shí ge xiǎoshí, yǒu jiābānfèi ma? | I worked ten hours of overtime this month. Is there overtime pay?\nB：有，會寫在薪資單上。 | Yǒu, huì xiě zài xīnzīdān shàng. | Yes, it''s written on the pay slip.\nA：薪資單上為什麼有扣錢？ | Xīnzīdān shàng wèishénme yǒu kòu qián? | Why is money deducted on the pay slip?\nB：那是勞健保和伙食費，我們一起看看。 | Nà shì láojiànbǎo hé huǒshífèi, wǒmen yìqǐ kànkan. | That''s labor and health insurance and the meal fee. Let''s look at it together.', E'職場溝通', E'Workplace Communication'),
    (22, E'照顧長者：日常照護', E'Caring for the Elderly: Daily Care', 2, E'稱呼長者、吃藥、量血壓、扶行與防跌倒、洗澡與翻身', E'Addressing the elderly, medicine, blood pressure, helping them walk and preventing falls, bathing and turning over', E'阿嬤，該吃藥了。 | Āmā, gāi chī yào le. | Grandma, it''s time to take your medicine.\n阿公，我扶你，小心跌倒。 | Āgōng, wǒ fú nǐ, xiǎoxīn diēdǎo. | Grandpa, I''ll support you. Be careful not to fall.\n我來幫您量血壓。 | Wǒ lái bāng nín liáng xuèyā. | Let me measure your blood pressure.', E'阿公 | āgōng | grandpa (elderly man)\n阿嬤 | āmā | grandma (elderly woman)\n吃藥 | chī yào | to take medicine\n量血壓 | liáng xuèyā | to measure blood pressure\n洗澡 | xǐzǎo | to bathe\n扶 | fú | to support, to hold up\n小心跌倒 | xiǎoxīn diēdǎo | careful not to fall\n輪椅 | lúnyǐ | wheelchair\n尿布 | niàobù | diaper\n翻身 | fānshēn | to turn over\n頭暈 | tóuyūn | dizzy\n正常 | zhèngcháng | normal', E'A：阿嬤，早安。今天覺得怎麼樣？ | Āmā, zǎo ān. Jīntiān juéde zěnmeyàng? | Grandma, good morning. How do you feel today?\nB：我有一點頭暈。 | Wǒ yǒu yìdiǎn tóuyūn. | I''m a little dizzy.\nA：請坐好，我來幫您量血壓。 | Qǐng zuò hǎo, wǒ lái bāng nín liáng xuèyā. | Please sit down. I''ll measure your blood pressure.\nB：好。 | Hǎo. | OK.\nA：血壓正常。吃完早餐，就要吃藥。 | Xuèyā zhèngcháng. Chī wán zǎocān, jiù yào chī yào. | Your blood pressure is normal. After breakfast, it''s time to take your medicine.\nB：好，謝謝你。 | Hǎo, xièxie nǐ. | OK, thank you.', E'照護工作', E'Caregiving Work'),
    (23, E'與雇主和家屬溝通', E'Talking with the Employer & Family', 2, E'回報長者今天的狀況、飲食與睡眠、回診安排、請家屬放心', E'Reporting the elderly person''s condition, meals and sleep, follow-up visits, reassuring the family', E'他今天沒有胃口，只吃了一點。 | Tā jīntiān méiyǒu wèikǒu, zhǐ chī le yìdiǎn. | He has no appetite today and only ate a little.\n請放心，我會照顧好阿公。 | Qǐng fàngxīn, wǒ huì zhàogù hǎo āgōng. | Please don''t worry. I''ll take good care of Grandpa.\n明天我會準備好健保卡。 | Míngtiān wǒ huì zhǔnbèi hǎo jiànbǎokǎ. | Tomorrow I''ll have the health insurance card ready.', E'雇主 | gùzhǔ | employer\n家屬 | jiāshǔ | family members\n睡得好 | shuì de hǎo | to sleep well\n沒有胃口 | méiyǒu wèikǒu | to have no appetite\n醒 | xǐng | to wake up\n回診 | huízhěn | follow-up visit\n預約 | yùyuē | appointment, to book\n健保卡 | jiànbǎokǎ | health insurance card\n藥袋 | yàodài | medicine bag\n準備 | zhǔnbèi | to prepare\n請放心 | qǐng fàngxīn | please don''t worry\n辛苦了 | xīnkǔ le | thank you for your hard work', E'A：王先生，阿公今天吃得不多。 | Wáng xiānshēng, āgōng jīntiān chī de bù duō. | Mr. Wang, Grandpa didn''t eat much today.\nB：他昨天晚上睡得好嗎？ | Tā zuótiān wǎnshang shuì de hǎo ma? | Did he sleep well last night?\nA：睡得不太好，醒了兩次。 | Shuì de bú tài hǎo, xǐng le liǎng cì. | Not very well. He woke up twice.\nB：好，謝謝你告訴我。明天要回診。 | Hǎo, xièxie nǐ gàosù wǒ. Míngtiān yào huízhěn. | OK, thanks for telling me. Tomorrow is the follow-up visit.\nA：我會準備好健保卡和藥袋。 | Wǒ huì zhǔnbèi hǎo jiànbǎokǎ hé yàodài. | I''ll prepare the health insurance card and the medicine bag.\nB：辛苦了。 | Xīnkǔ le. | Thank you for your hard work.', E'照護工作', E'Caregiving Work'),
    (25, E'看醫生與藥局', E'Seeing a Doctor & the Pharmacy', 2, E'掛號、說明症狀、藥物過敏、聽懂醫生的交代、去藥局買藥', E'Registering, describing symptoms, drug allergies, understanding the doctor, buying medicine at a pharmacy', E'我頭痛，肚子也痛。 | Wǒ tóutòng, dùzi yě tòng. | I have a headache and my stomach hurts too.\n這個藥一天吃幾次？ | Zhège yào yì tiān chī jǐ cì? | How many times a day do I take this medicine?\n請問哪裡有藥局？ | Qǐngwèn nǎlǐ yǒu yàojú? | Excuse me, where is there a pharmacy?', E'掛號 | guàhào | to register (at a clinic)\n咳嗽 | késòu | to cough\n頭痛 | tóutòng | headache\n肚子痛 | dùzi tòng | stomach ache\n拉肚子 | lā dùzi | to have diarrhea\n過敏 | guòmǐn | allergic\n藥物 | yàowù | medicine\n開藥 | kāi yào | to prescribe medicine\n藥局 | yàojú | pharmacy\n一天三次 | yì tiān sān cì | three times a day\n飯後 | fànhòu | after meals\n多喝水 | duō hē shuǐ | drink more water', E'A：醫生，我從昨天開始發燒，還有一點咳嗽。 | Yīshēng, wǒ cóng zuótiān kāishǐ fāshāo, hái yǒu yìdiǎn késòu. | Doctor, I''ve had a fever since yesterday and a little cough.\nB：你對藥物過敏嗎？ | Nǐ duì yàowù guòmǐn ma? | Are you allergic to any medicine?\nA：沒有，我不會過敏。 | Méiyǒu, wǒ bú huì guòmǐn. | No, I''m not allergic.\nB：我開藥給你，一天三次，飯後吃。 | Wǒ kāi yào gěi nǐ, yì tiān sān cì, fànhòu chī. | I''ll prescribe medicine for you: three times a day, after meals.\nA：我還需要注意什麼？ | Wǒ hái xūyào zhùyì shénme? | What else should I pay attention to?\nB：要多喝水，好好休息。 | Yào duō hē shuǐ, hǎohāo xiūxí. | Drink more water and rest well.', E'健康與緊急', E'Health & Emergencies'),
    (26, E'緊急求助與報警', E'Emergency Help & Calling the Police', 2, E'求救、撥打一一九與一一零、說明地點與狀況、回答接線人員的問題', E'Calling for help, dialing 119 and 110, giving your location and the situation, answering the operator', E'救命！請叫救護車。 | Jiùmìng! Qǐng jiào jiùhùchē. | Help! Please call an ambulance.\n有人受傷了，流了很多血。 | Yǒu rén shòushāng le, liú le hěn duō xuè. | Someone is hurt and bleeding a lot.\n失火了，請快一點來！ | Shīhuǒ le, qǐng kuài yìdiǎn lái! | There''s a fire! Please come quickly!', E'救命 | jiùmìng | help!\n救護車 | jiùhùchē | ambulance\n警察 | jǐngchá | police\n火災 | huǒzāi | fire\n昏倒 | hūndǎo | to faint\n流血 | liúxuè | to bleed\n呼吸 | hūxī | to breathe\n派 | pài | to send, to dispatch\n地址 | dìzhǐ | address\n不要動 | búyào dòng | do not move\n快一點 | kuài yìdiǎn | hurry\n我在這裡 | wǒ zài zhèlǐ | I am here', E'A：喂，一一九嗎？有人昏倒了，請派救護車。 | Wéi, yāo yāo jiǔ ma? Yǒu rén hūndǎo le, qǐng pài jiùhùchē. | Hello, is this 119? Someone has fainted. Please send an ambulance.\nB：請問你在哪裡？ | Qǐngwèn nǐ zài nǎlǐ? | Where are you?\nA：我在中山路三十號，工廠門口。 | Wǒ zài Zhōngshān Lù sānshí hào, gōngchǎng ménkǒu. | I''m at No. 30 Zhongshan Road, at the factory entrance.\nB：他有呼吸嗎？ | Tā yǒu hūxī ma? | Is he breathing?\nA：有，可是他沒有醒來。 | Yǒu, kěshì tā méiyǒu xǐnglái. | Yes, but he hasn''t woken up.\nB：好，不要移動他，救護車馬上到。 | Hǎo, búyào yídòng tā, jiùhùchē mǎshàng dào. | OK. Don''t move him. The ambulance will arrive right away.', E'健康與緊急', E'Health & Emergencies')
  ) AS v(position, name, name_en, hours, topics, topics_en, examples, vocabulary, dialogue, category, category_en)
  ON CONFLICT (course_id, name) DO NOTHING
  RETURNING id
)
SELECT count(*) AS added FROM inserted \gset
SELECT :added > 0 AS did_add \gset

-- 既有單元補上場合分類（只補還沒有分類的）。
UPDATE hr_tc_course_units u SET category = v.category, category_en = v.category_en, updated_at = NOW()
FROM (VALUES
    (E'發音與聲調', E'基礎', E'Basics'),
    (E'問候與自我介紹', E'基礎', E'Basics'),
    (E'數字、時間、日期', E'基礎', E'Basics'),
    (E'日常生活', E'購物與飲食', E'Shopping & Food'),
    (E'住宿與宿舍生活', E'住宿與生活服務', E'Housing & Services'),
    (E'職場基本用語', E'職場溝通', E'Workplace Communication'),
    (E'身體與緊急狀況', E'健康與緊急', E'Health & Emergencies'),
    (E'複習與結業測驗', E'複習', E'Review')
) AS v(name, category, category_en)
WHERE u.course_id = :course_id AND u.name = v.name AND u.category = '';

-- 這次有新增單元時，依場合重新排列順序（只調整本腳本認得的單元）。
\if :did_add
UPDATE hr_tc_course_units u SET position = v.position, updated_at = NOW()
FROM (VALUES
    (E'發音與聲調', 1),
    (E'問候與自我介紹', 2),
    (E'數字、時間、日期', 3),
    (E'日常生活', 4),
    (E'買菜與市場', 5),
    (E'便利商店與超市', 6),
    (E'餐廳點餐', 7),
    (E'公車與捷運', 8),
    (E'火車與高鐵', 9),
    (E'問路與計程車', 10),
    (E'住宿與宿舍生活', 11),
    (E'宿舍報修與生活規則', 12),
    (E'銀行與匯款', 13),
    (E'打電話與傳訊息', 14),
    (E'職場基本用語', 15),
    (E'報到與認識同事', 16),
    (E'聽懂主管指令', 17),
    (E'請假、遲到與調班', 18),
    (E'安全規定與危險警告', 19),
    (E'回報問題與請求協助', 20),
    (E'薪水、加班與工時', 21),
    (E'照顧長者：日常照護', 22),
    (E'與雇主和家屬溝通', 23),
    (E'身體與緊急狀況', 24),
    (E'看醫生與藥局', 25),
    (E'緊急求助與報警', 26),
    (E'複習與結業測驗', 27)
) AS v(name, position)
WHERE u.course_id = :course_id AND u.name = v.name;
\endif

COMMIT;
\echo '完成：新增單元數（0 代表之前已經新增過）：' :added
